draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // eggplant
  ctx.fillStyle = '#5c0011'; // eggplant purple
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // antioxidant symbol (a simple plus sign with a circle)
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 70, H/2, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + 70, H/2 - 20);
  ctx.lineTo(W/2 + 70, H/2 + 20);
  ctx.moveTo(W/2 + 50, H/2);
  ctx.lineTo(W/2 + 90, H/2);
  ctx.stroke();

  // oscillating antioxidant symbol
  ctx.save();
  ctx.translate(W/2 + 70, H/2);
  ctx.rotate(Math.sin(t));
  ctx.beginPath();
  ctx.arc(0, 0, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(0, -20);
  ctx.lineTo(0, 20);
  ctx.moveTo(-20, 0);
  ctx.lineTo(20, 0);
  ctx.stroke();
  ctx.restore();

  ctx.restore();
}
